+            this.in = in;
+            this.fileOffset = fileOffset;
+            this.bytesReadTracker = bytesReadTracker;
+        }
+
+        @Override
+        public void close() throws IOException {
+            in.close();
+        }
+
+        @Override
+        public long getFilePointer() {
+            return in.getFilePointer();
+        }
+
+        @Override
+        public void seek(long pos) throws IOException {
